/**
 * Project freeze: while a project is archived, its issues and everything attached to them are read-only.
 *
 * Must call (do not reimplement): isArchived, AlreadyArchivedError
 */
import { AlreadyArchivedError, isArchived } from "@/lib/soft-delete";
import * as projectRepo from "@/server/repositories/project-repository";
import { requireFound } from "./_support";
import type { Issue } from "@/types/issue";

/**
 * Throws `AlreadyArchivedError` when the issue's parent project is archived.
 * Callers run this after their own permission and archived-row checks, so
 * those keep precedence over the freeze.
 */
export async function assertProjectNotFrozen(issue: Issue): Promise<void> {
  const project = requireFound(
    await projectRepo.findProjectById(issue.orgId, issue.projectId),
    "Project",
    issue.projectId,
  );

  if (isArchived(project)) {
    throw new AlreadyArchivedError("Issue", issue.id);
  }
}

